mapper.select:
SELECT *
FROM message_participant
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND participant_type = #{participantType}
  AND participant_id = #{participantId}
  AND participant_status = 'ACTIVE'
  AND del_flag = '0'
LIMIT 1

mapper.update:
UPDATE message_participant p
INNER JOIN message_conversation c ON c.tenant_id = #{tenantId}
    AND c.id = p.conversation_id
    AND c.del_flag = '0'
SET p.last_read_seq = #{lastReadSeq}, p.update_time = NOW()
WHERE p.tenant_id = #{tenantId}
  AND p.conversation_id = #{conversationId}
  AND p.participant_type = #{participantType}
  AND p.participant_id = #{participantId}
  AND p.participant_status = 'ACTIVE'
  AND p.del_flag = '0'
  AND p.last_read_seq < #{lastReadSeq}
  AND #{lastReadSeq} <= c.last_seq

UPDATE message_participant
SET participant_status = 'EXITED', exited_time = NOW(), update_time = NOW()
WHERE tenant_id = #{tenantId}
  AND conversation_id = #{conversationId}
  AND participant_type = #{participantType}
  AND participant_id = #{participantId}
  AND participant_status = 'ACTIVE'
  AND del_flag = '0'
